def generate_signals(df: pd.DataFrame) -> pd.Series:
    ma_short = df['close'].rolling(window=5).mean()
    ma_long = df['close'].rolling(window=20).mean()
    signals = (ma_short > ma_long).astype(int)
    return signals.shift(1).fillna(0)

def generate_signals(df: pd.DataFrame) -> pd.Series:
    fast_ma = df['close'].rolling(window=5).mean()
    slow_ma = df['close'].rolling(window=20).mean()
    return ((fast_ma > slow_ma) & fast_ma.notna()).astype(int)
